'use client';

import { useState, useEffect } from 'react';

interface Product {
  _id: string;
  name: string;
  asin: string;
  url: string;
  priceHistory: { price: number; date: string }[];
  thresholdPrice: number;
  trackedBy: number[];
}

export default function Home() {
  const [products, setProducts] = useState<Product[]>([]);

  useEffect(() => {
    async function fetchProducts() {
      const res = await fetch('/api/products');
      const data = await res.json();
      setProducts(data);
    }
    fetchProducts();
  }, []);

  return (
    <main className="flex min-h-screen flex-col items-center justify-between p-24">
      <h1 className="text-4xl font-bold mb-8">Tracked Products</h1>
      <div className="w-full">
        <table className="w-full table-auto border-collapse border border-gray-400">
          <thead>
            <tr className="bg-gray-200">
              <th className="border border-gray-300 px-4 py-2">Name</th>
              <th className="border border-gray-300 px-4 py-2">ASIN</th>
              <th className="border border-gray-300 px-4 py-2">URL</th>
              <th className="border border-gray-300 px-4 py-2">Current Price</th>
              <th className="border border-gray-300 px-4 py-2">Threshold Price</th>
              <th className="border border-gray-300 px-4 py-2">Tracked By</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product) => (
              <tr key={product._id}>
                <td className="border border-gray-300 px-4 py-2">{product.name}</td>
                <td className="border border-gray-300 px-4 py-2">{product.asin}</td>
                <td className="border border-gray-300 px-4 py-2"><a href={product.url} target="_blank" rel="noopener noreferrer">Link</a></td>
                <td className="border border-gray-300 px-4 py-2">{product.priceHistory.slice(-1)[0]?.price || 'N/A'}</td>
                <td className="border border-gray-300 px-4 py-2">{product.thresholdPrice}</td>
                <td className="border border-gray-300 px-4 py-2">{product.trackedBy.length}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </main>
  );
}